import React from 'react';
import { useData } from '../components/DataLoader';
import { Container, Row, Col, Button } from 'react-bootstrap';
import CalendarEmbed from '../components/CalendarEmbed';
import VerticalNewsCarousel from '../components/VerticalNewsCarousel';
import { useNavigate } from 'react-router-dom';
import { useLanguage } from '../components/LanguageProvider';

function Home() {

  const {language} = useLanguage();
  const { data } = useData();

  const navigate = useNavigate();

  const homepageTitle = data.news?.[0]?.homepage_title || 
    (language !== 'fr' 
      ? "Welcome to Phaedra Royle's research laboratory" 
      : 'Bienvenue sur le laboratoire de recherche de Phaedra Royle');
  
  const homepageDescription = data.news?.[0]?.homepage_description || 
    (language !== 'fr' 
      ? "Advancing knowledge in speech-language pathology." 
      : "Pour faire avancer les connaissances en Orthophonie.");

  const handleLearnMore = () => {
    navigate('/research', { state: { smoothScroll: true } });
  };


  return (
  
    <>
    <Container className="my-5">
      <Row>
        <Col>
          <h1>{homepageTitle}</h1>
          <br />
          <p>{homepageDescription}</p>
          <Button variant="primary" onClick={handleLearnMore}> {language !== 'fr' ? "Read more"  : "En savoir plus" }</Button>
          <img src={process.env.PUBLIC_URL + '/images/group.png'} alt="Research Lab" className="img-fluid" />
        </Col>
      </Row>
      
    </Container>

    <Container fluid className="calendar-section py-4" style={{ backgroundColor: '#F1F2FA' }}>
      <Container>
        <h2 className="mb-1"> {language !== 'fr' ? "Upcoming"  :"Évènements" } </h2>
        <h2 className="mb-3">{language !== 'fr' ? "events"  :"à venir" }</h2>
        <Row>
          <Col>
            <CalendarEmbed/>
          </Col>
        </Row>
      </Container>
    </Container>

    <Container fluid className="my-5 p-0">
      <Container className="my-5">
        <br />
        <h2 className="custom-margin-top"> {language !== 'fr' ? "Latest news "  :"Actualités" } </h2>
        <br />
        <VerticalNewsCarousel />
        


        </Container>

    </Container>

    </>

    
  );
}

export default Home;